package com.astrocare.controller; import com.astrocare.service.ReportService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports") @RequiredArgsConstructor public class ReportController {private final ReportService service; @GetMapping("/pdf/{astronautId}") @PreAuthorize("hasRole('FLIGHT_SURGEON')") public ResponseEntity<byte[]> pdf(@PathVariable Long astronautId)throws Exception{return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=astrocare-"+astronautId+".pdf").body(service.pdf(astronautId));}}
